ALTER TABLE "realtime_sessions" ADD CONSTRAINT "realtime_sessions_end_reason_state_check" CHECK ("realtime_sessions"."end_reason" is null or (state = 'ended' and end_reason in ('hung_up', 'safety_block', 'safety_enforcement', 'reconnect_expired', 'provider_failed', 'operator_terminated')) or (state = 'expired' and end_reason in ('invitation_expired')) or (state = 'rejected' and end_reason in ('declined')) or (state = 'cancelled' and end_reason in ('withdrawn')) or (state = 'failed' and end_reason in ('provider_unavailable', 'provider_failed', 'join_timeout')));
